mapper.select:
	SELECT
	SUM(coalesce(iti.TRADE_AMOUNT ,0)) as ii
FROM
	ins_tra_investment iti 
WHERE
	iti.REL_NUMBER = #{param1} 
	AND date( iti.BUS_START_TIME ) > #{param2}
	AND date( iti.BUS_START_TIME ) < #{param3} 
	
	AND TENANT_ID_ = #{param4}
	
	AND iti.DELFLAG_ = '1'

	SELECT
	SUM(coalesce(itf.TRADE_AMOUNT ,0)) as a
FROM
	ins_tra_funds itf  
WHERE
	itf.REL_NUMBER = #{param1} 
	AND date( itf.BUS_START_TIME ) > #{param2}
	AND date( itf.BUS_START_TIME ) < #{param3} 
	
	AND TENANT_ID_ = #{param4}
	
	AND itf.DELFLAG_ = '1'

	SELECT
	SUM(coalesce(itb.TRADE_AMOUNT ,0)) as b
FROM
	ins_tra_business itb
WHERE
	itb.REL_NUMBER = #{param1} 
	AND date( itb.BUS_START_TIME ) > #{param2}
	AND date( itb.BUS_START_TIME ) < #{param3} 
	
	AND TENANT_ID_ = #{param4}
	
	AND itb.DELFLAG_ = '1'

	SELECT
	SUM(coalesce(it.TRADE_AMOUNT ,0)) as c
FROM
	ins_tra_interest it 
WHERE
	it.REL_NUMBER = #{param1} 
	AND date( it.BUS_START_TIME ) > #{param2}
	AND date( it.BUS_START_TIME ) < #{param3} 
	
	AND TENANT_ID_ = #{param4}
	
	AND it.DELFLAG_ = '1'

	SELECT
	SUM(coalesce(its.TRADE_AMOUNT ,0)) as d
FROM
	ins_tra_service its 
WHERE
	its.REL_NUMBER = #{param1} 
	AND date( its.BUS_START_TIME ) > #{param2}
	AND date( its.BUS_START_TIME ) < #{param3} 
	
	AND TENANT_ID_ = #{param4}
	
	AND its.DELFLAG_ = '1'
